<?php require 'config.php';require_role('customer');$s=$pdo->prepare("SELECT o.*,r.name restaurant_name FROM orders o JOIN restaurants r ON r.id=o.restaurant_id WHERE customer_id=? ORDER BY o.id DESC");$s->execute([current_user()['id']]);$orders=$s->fetchAll();$pageTitle='My orders';include 'partials/header.php';?><h1>My orders</h1><div class="table-wrap"><table><tr><th>Order</th><th>Restaurant</th><th>Total</th><th>Status</th><th>Date</th></tr><?php foreach($orders as $o):?><tr><td>#<?=$o['id']?></td><td><?=e($o['restaurant_name'])?></td><td>৳<?=number_format((float)$o['total'],2)?></td><td><span class="status"><?=e($o['status'])?></span></td><td><?=e($o['created_at'])?></td></tr><?php endforeach;?></table></div><?php if(!$orders):?><p>You have not placed any orders yet.</p><?php endif;?><?php include 'partials/footer.php';?>
